async function marketplaceConversationOrThrow(db, conversationId, myCompanyId) {
  const conversation = (await db.select().from(marketplaceConversations).where(eq(marketplaceConversations.id, conversationId)).limit(1))[0];
  if (!conversation || conversation.ownerCompanyId !== myCompanyId && conversation.inquirerCompanyId !== myCompanyId) {
    throw new Error("Conversation not found.");
  }
  return conversation;
}
async function marketplaceCompanyNames(db, companyIds) {
  const unique = [...new Set(companyIds.filter((id) => Number.isInteger(id) && id > 0))];
  if (!unique.length)
    return new Map;
  const rows = await db.select({ companyId: settings.companyId, companyName: settings.companyName }).from(settings).where(inArray(settings.companyId, unique));
  return new Map(rows.map((row) => [row.companyId, row.companyName || `Company ${row.companyId}`]));
}
