  userSupportThreads: defineAction({
    request: object({}),
    response: object({
      threads: array(object({
        id: number2(),
        kind: string2(),
        subject: string2(),
        message: string2(),
        status: string2(),
        replyCount: number2(),
        lastReply: object({ sender: string2(), message: string2(), createdAt: string2() }).nullable(),
        createdAt: string2(),
        updatedAt: string2()
      }))
    }),
    async handler(ctx) {
      const identity = workspaceIdentity(ctx);
      const db = ctx.db();
      const reports = await db.select().from(platformSupportReports).where(eq(platformSupportReports.userId, identity.workspaceUserId)).orderBy(desc(platformSupportReports.createdAt), desc(platformSupportReports.id));
      const reportIds = reports.map((r) => r.id);
      const replyRows = reportIds.length ? await db.select().from(platformSupportReplies).where(inArray(platformSupportReplies.reportId, reportIds)) : [];
      const byReport = new Map;
      for (const reply of replyRows) {
        const list = byReport.get(reply.reportId) ?? [];
        list.push({ id: reply.id, sender: reply.sender, message: reply.message, createdAt: reply.createdAt });
        byReport.set(reply.reportId, list);
      }
      return {
        threads: reports.map((r) => {
          const replies = (byReport.get(r.id) ?? []).sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
          const latest = replies[0] ?? null;
          return {
            id: r.id,
            kind: r.kind,
            subject: r.subject,
            message: r.message,
            status: r.status,
            replyCount: replies.length,
            lastReply: latest ? { sender: latest.sender, message: latest.message.slice(0, 120), createdAt: latest.createdAt.toISOString() } : null,
            createdAt: r.createdAt.toISOString(),
            updatedAt: r.updatedAt.toISOString()
          };
        })
      };
    }
  }),
